/*
 * Д-33. Расписка: в получении денег в долг (пишет заёмщик) или в получении возврата долга (пишет займодавец).
 * Основа: ст. 807 (заём между гражданами заключён с момента передачи денег), п. 1 ст. 808 (письменная форма, если
 * сумма больше 10 000 ₽), п. 2 ст. 808 (расписка подтверждает договор и его условия), п. 1 ст. 809 (без условия о
 * размере процентов — ключевая ставка ЦБ), п. 4 ст. 809 (между гражданами до 100 000 ₽ — предполагается беспроцентным),
 * п. 1 ст. 810 (без срока — 30 дней со дня требования), п. 1 ст. 811 (проценты по ст. 395 за просрочку возврата),
 * п. 2 ст. 408 ГК (расписка кредитора в получении исполнения; при невозможности вернуть долговой документ — указать это).
 * Статус: ЧЕРНОВИК, не проверен юристом.
 */
(function (global) {
  "use strict";
  const { U } = global.Engine;
  const C = global.Common;
  const F = U.F;

  const person = (prefix, who) => [
    { id: prefix + "_name", type: "text", label: `ФИО ${who} полностью` },
    { id: prefix + "_birth", type: "date", label: "Дата рождения", required: false },
    { id: prefix + "_passport", type: "text", label: "Паспорт: серия, номер, кем и когда выдан", required: false,
      hint: "Оставьте пустым — будет строка, чтобы вписать от руки. Данные остаются в вашем браузере",
      placeholder: "45 12 345678, выдан ГУ МВД России по г. Москве 01.02.2020" },
    { id: prefix + "_address", type: "text", label: "Адрес регистрации" },
  ];

  function derive(a) {
    const amount = typeof a.amount === "number" && a.amount > 0 ? a.amount : null;
    const due = U.date(a.due_date);
    const writtenDate = U.date(a.doc_date);
    const rate = typeof a.rate === "number" ? a.rate : null;
    const keyNow = C.keyRate(U.today());
    return { amount, due, writtenDate, rate, keyNow, over100: amount != null && amount > 100000, over10: amount != null && amount > 10000 };
  }

  const who = (a, prefix) => {
    const b = U.date(a[prefix + "_birth"]);
    return `${F(a[prefix + "_name"], "ФИО")}` + (b ? `, ${U.fmtDate(b)} г. р.` : "") + `, ${C.passport(a[prefix + "_passport"])}, зарегистрированный(ая) по адресу: ${F(a[prefix + "_address"], "адрес")}`;
  };

  const spec = {
    id: "d33",
    code: "Д-33",
    title: "Расписка в получении денег",
    lead: "Расписка в получении денег в долг или в получении возврата долга. Займёт около 5 минут.",
    status: "draft",
    disclaimer: "Расписка составлена по вашим ответам и не является юридической консультацией.",

    steps: [
      {
        id: "kind", title: "Что за расписка",
        questions: [
          { id: "kind", type: "choice", label: "Какая расписка нужна?", options: [
            { value: "loan", label: "Деньги дают в долг", hint: "Пишет и подписывает тот, кто берёт деньги (заёмщик)" },
            { value: "repay", label: "Долг возвращают", hint: "Пишет и подписывает тот, кому возвращают деньги (займодавец)" },
          ] },
          { id: "city", type: "text", label: "Город, где составляется расписка", placeholder: "г. Москва" },
          { id: "doc_date", type: "date", future: true, label: "Дата расписки" },
          { id: "amount", type: "money", label: "Сумма", suffix: "₽", min: 1, hint: "Только рубли. Сумма в документе будет написана и цифрами, и прописью" },
          { id: "how", type: "choice", label: "Как передаются деньги?", options: [
            { value: "cash", label: "Наличными при подписании" },
            { value: "transfer", label: "Банковским переводом" },
          ] },
          { id: "transfer_date", type: "date", future: true, label: "Дата перевода", show: a => a.how === "transfer" },
        ],
      },
      {
        id: "terms", title: "Условия долга",
        show: a => a.kind === "loan",
        questions: [
          { id: "return", type: "choice", label: "Когда вернуть?", show: a => a.kind === "loan", options: [
            { value: "date", label: "До определённой даты" },
            { value: "demand", label: "По требованию", hint: "Тогда долг возвращается в течение 30 дней после того, как займодавец потребует" },
          ] },
          { id: "due_date", type: "date", future: true, label: "Вернуть не позднее", show: a => a.kind === "loan" && a.return === "date",
            validate: (v, a) => { const s = U.date(a.doc_date), x = U.date(v); return s && x && x <= s ? "Дата возврата должна быть позже даты расписки" : null; } },
          { id: "interest", type: "choice", label: "Проценты за пользование деньгами?", show: a => a.kind === "loan",
            hint: "Если процентов нет, в расписке будет прямо написано, что заём беспроцентный. Без этой фразы при сумме больше 100 000 ₽ проценты начисляются по ключевой ставке ЦБ", options: [
            { value: "none", label: "Без процентов" },
            { value: "rate", label: "С процентами" },
          ] },
          { id: "rate", type: "number", label: "Сколько процентов годовых?", suffix: "% годовых", min: 0.01, show: a => a.kind === "loan" && a.interest === "rate" },
          { id: "rate_pay", type: "choice", label: "Когда платить проценты?", show: a => a.kind === "loan" && a.interest === "rate", options: [
            { value: "monthly", label: "Каждый месяц", hint: "Так по закону, если не договорились иначе" },
            { value: "end", label: "Вместе с возвратом долга" },
          ] },
          { id: "penalty", type: "choice", label: "Что будет, если не вернут вовремя?", show: a => a.kind === "loan", options: [
            { value: "law", label: "Проценты по закону", hint: "По ключевой ставке ЦБ за каждый день просрочки (ст. 395 ГК)" },
            { value: "custom", label: "Своя неустойка — процент в день" },
          ] },
          { id: "penalty_rate", type: "number", label: "Неустойка, % в день от невозвращённой суммы", suffix: "% в день", min: 0.01, show: a => a.kind === "loan" && a.penalty === "custom",
            hint: "Часто ставят 0,1% в день. Слишком большую неустойку суд может уменьшить (ст. 333 ГК)" },
        ],
      },
      {
        id: "repay", title: "Возврат",
        show: a => a.kind === "repay",
        questions: [
          { id: "basis", type: "choice", label: "Чем был оформлен долг?", show: a => a.kind === "repay", options: [
            { value: "receipt", label: "Распиской" },
            { value: "contract", label: "Договором займа" },
          ] },
          { id: "basis_date", type: "date", label: "Дата расписки или договора", show: a => a.kind === "repay" },
          { id: "full", type: "choice", label: "Долг возвращён полностью?", show: a => a.kind === "repay", options: [
            { value: "all", label: "Да, долг и проценты — претензий нет" },
            { value: "principal", label: "Основной долг — да, но остались проценты или неустойка" },
            { value: "part", label: "Нет, вернули часть" },
          ] },
          { id: "left", type: "money", label: "Сколько ещё должны после этого платежа?", suffix: "₽", min: 1, show: a => a.kind === "repay" && a.full === "part" },
          { id: "original", type: "choice", label: "Что с оригиналом расписки или договора?", show: a => a.kind === "repay" && a.full !== "part", options: [
            { value: "returned", label: "Возвращаю заёмщику" },
            { value: "lost", label: "Потерян — вернуть не могу" },
            { value: "keep", label: "Не упоминать" },
          ] },
        ],
      },
      {
        id: "parties", title: "Стороны",
        questions: [
          ...person("lender", "того, кто даёт деньги в долг (займодавца)"),
          ...person("borrower", "того, кто берёт деньги в долг (заёмщика)"),
        ],
      },
    ],

    derive,

    render(a, d) {
      const P = [];
      const T = t => P.push({ text: t, indent: true });
      const loan = a.kind !== "repay";
      P.push({ text: "РАСПИСКА", align: "center", bold: true, after: 0 });
      P.push({ text: loan ? "в получении денежных средств в долг" : "в получении денежных средств в счёт возврата займа", align: "center", after: 240 });
      P.push({ text: `${F(a.city, "город")}                                                                          ${F(U.fmtDateLong(d.writtenDate), "дата")}`, align: "left", after: 240 });
      const money = d.amount ? C.rubles(d.amount) : F(null, "сумма");
      const how = a.how === "transfer"
        ? `путём перевода на мой банковский счёт ${F(U.fmtDate(U.date(a.transfer_date)), "дата перевода")}`
        : "наличными в момент составления настоящей расписки";

      if (loan) {
        T(`Я, ${who(a, "borrower")}, получил(а) от ${who(a, "lender")}, денежные средства в размере ${money} в качестве займа.`);
        T(`Денежные средства получены ${how}.` + (a.how !== "transfer" ? " Деньги пересчитаны мною, претензий по сумме не имею." : ""));
        if (a.return === "demand") T("Обязуюсь вернуть сумму займа в течение тридцати дней со дня предъявления займодавцем требования о возврате (п. 1 ст. 810 ГК РФ).");
        else T(`Обязуюсь вернуть сумму займа в срок не позднее ${F(U.fmtDate(d.due), "дата возврата")} включительно.`);
        if (a.interest === "rate") T(`За пользование займом обязуюсь уплачивать проценты в размере ${F(d.rate != null ? String(d.rate).replace(".", ",") : null, "ставка")}% годовых, начисляемые на сумму займа со дня, следующего за днём его получения, по день возврата включительно. Проценты уплачиваются ${a.rate_pay === "end" ? "одновременно с возвратом суммы займа" : "ежемесячно"}.`);
        else if (a.interest === "none") T("Заём является беспроцентным: проценты за пользование займом не начисляются.");
        else T(F(null, "проценты"));
        if (a.penalty === "custom") T(`В случае невозврата суммы займа в срок обязуюсь уплатить неустойку в размере ${F(a.penalty_rate != null ? String(a.penalty_rate).replace(".", ",") : null, "процент")}% от невозвращённой суммы за каждый день просрочки.`);
        else T("В случае невозврата суммы займа в срок на неё подлежат уплате проценты в размере, предусмотренном п. 1 ст. 395 ГК РФ, со дня, когда она должна была быть возвращена, по день её возврата (п. 1 ст. 811 ГК РФ).");
        T("Сумму займа возвращаю " + (a.how === "transfer" ? "переводом на банковский счёт займодавца либо наличными под расписку займодавца." : "наличными под расписку займодавца либо переводом на банковский счёт займодавца."));
        T("Расписка составлена мною добровольно, её содержание мне понятно.");
        P.push({ text: `Заёмщик:\n\n____________________ (подпись)\n\n__________________________________________________\n(фамилия, имя, отчество полностью, собственноручно)`, align: "left", before: 360 });
      } else {
        const basis = a.basis === "contract" ? "договору займа" : "расписке";
        T(`Я, ${who(a, "lender")}, получил(а) от ${who(a, "borrower")}, денежные средства в размере ${money} в счёт возврата займа по ${basis} от ${F(U.fmtDate(U.date(a.basis_date)), "дата")}.`);
        T(`Денежные средства получены ${how}.`);
        if (a.full === "all") T("Обязательства заёмщика по возврату займа и уплате процентов исполнены полностью. Претензий к заёмщику по указанному займу не имею.");
        else if (a.full === "principal") T("Сумма займа (основной долг) возвращена полностью. Настоящая расписка не освобождает заёмщика от уплаты процентов и неустойки, начисленных по указанному займу.");
        else if (a.full === "part") T(`Заём возвращён частично. Остаток задолженности по сумме займа после получения настоящего платежа составляет ${typeof a.left === "number" ? C.rubles(a.left) : F(null, "остаток")}.`);
        else T(F(null, "полностью или частично"));
        if (a.original === "returned") T(`Оригинал ${a.basis === "contract" ? "договора займа" : "расписки"} от ${F(U.fmtDate(U.date(a.basis_date)), "дата")} возвращён заёмщику.`);
        if (a.original === "lost") T(`Возвратить заёмщику оригинал ${a.basis === "contract" ? "договора займа" : "расписки"} от ${F(U.fmtDate(U.date(a.basis_date)), "дата")} невозможно в связи с его утратой (п. 2 ст. 408 ГК РФ).`);
        P.push({ text: `Займодавец:\n\n____________________ (подпись)\n\n__________________________________________________\n(фамилия, имя, отчество полностью, собственноручно)`, align: "left", before: 360 });
      }
      return P;
    },

    guidance(a, d) {
      const g = [];
      if (a.kind !== "repay") {
        g.push({ title: "Надёжнее всего — переписать расписку от руки.", text: "Печатная расписка с подписью тоже действует. Но если заёмщик перепишет текст сам, потом ему будет трудно сказать, что он её не писал: почерк проверит экспертиза. Минимум — пусть сам впишет ФИО полностью и поставит подпись." });
        g.push({ title: "Оригинал хранит тот, кто дал деньги.", text: "Заёмщику можно оставить копию. Если деньги перевели на карту, сохраните и выписку о переводе с назначением «заём по расписке от такой-то даты»." });
        if (a.interest === "rate" && d.rate != null && d.keyNow && d.rate > d.keyNow * 2) g.push({ title: "Высокие проценты суд может снизить.", text: `Если ставка в два и более раза выше обычной для таких займов, суд может уменьшить её до обычной (п. 5 ст. 809 ГК). Сейчас ключевая ставка ЦБ — ${String(d.keyNow).replace(".", ",")}%.` });
        if (a.return === "demand") g.push({ title: "Как потребовать долг.", text: "Отправьте заёмщику письменное требование (документ Д-35) ценным письмом с описью. Через 30 дней после получения долг просрочен." });
        g.push({ title: "Для займа больше 10 000 ₽ нужна письменная форма.", text: "Расписка её и заменяет (ст. 808 ГК). Свидетели и нотариус не обязательны." });
      } else {
        g.push({ title: "Заберите оригинал расписки или договора.", text: "Должник вправе его потребовать. Если оригинал на руках у займодавца, по нему могут снова потребовать деньги." });
        g.push({ title: "Возвращайте долг так, чтобы оставался след.", text: "Перевод на счёт займодавца с назначением «возврат займа по расписке от…» — сам по себе доказательство. Наличные — только под такую расписку." });
      }
      return g;
    },

    fileName(a) { return (a.kind === "repay" ? "Расписка о возврате долга" : "Расписка в получении денег в долг") + (a.borrower_name ? " — " + U.shortName(a.borrower_name) : ""); },
  };

  global.DOCS = global.DOCS || {};
  global.DOCS.d33 = spec;
})(typeof window !== "undefined" ? window : globalThis);
